import graph.*;
import dsu.*;
import mst.*;
import connectivity.*;
import shortestpath.*;
import java.util.*;
import java.nio.file.*;

public class Main {
 static final int[][] SIZES={{10,30},{100,500},{1000,5000}};
 static Graph undirected(int n,int m,long seed){Random r=new Random(seed);Graph g=new Graph(n,false);Set<Long> seen=new HashSet<>();for(int i=1;i<n;i++)add(g,seen,i,r.nextInt(i),1+r.nextInt(100));while(g.edges.size()<m){int a=r.nextInt(n),b=r.nextInt(n);if(a!=b)add(g,seen,a,b,1+r.nextInt(100));}return g;}
 static void add(Graph g,Set<Long>s,int a,int b,int w){long key=((long)Math.min(a,b)<<32)|Math.max(a,b);if(s.add(key))g.add(a,b,w);}
 static Graph directed(int n,int m,long seed,boolean dag){Random r=new Random(seed);Graph g=new Graph(n,true);Set<Long>s=new HashSet<>();while(g.edges.size()<m){int a=r.nextInt(n),b=r.nextInt(n);if(dag&&a>b){int t=a;a=b;b=t;}if(a==b)continue;long k=((long)a<<32)|b;if(s.add(k))g.add(a,b,1+r.nextInt(100));}return g;}
 interface Job {long run();}
 static double bench(Job j){for(int i=0;i<3;i++)j.run();long sum=0;for(int i=0;i<5;i++){long t=System.nanoTime();j.run();sum+=System.nanoTime()-t;}return sum/5e6;}
 static void check(boolean b,String msg){if(!b)throw new AssertionError(msg);}
 static void tests(){Graph g=new Graph(4,false);g.add(0,1,1);g.add(1,2,2);g.add(0,2,3);g.add(2,3,4);check(MST.kruskal(g).weight==7,"Kruskal");check(MST.prim(g).weight==7,"Prim");check(Dijkstra.run(g,0).dist[3]==7,"Dijkstra");Graph disconnected=new Graph(3,false);disconnected.add(0,1,1);check(!MST.kruskal(disconnected).connected,"Disconnected Kruskal");check(!MST.prim(disconnected).connected,"Disconnected Prim");check(Dijkstra.run(disconnected,0).dist[2]==Long.MAX_VALUE,"Unreachable");Graph one=new Graph(1,false);check(MST.kruskal(one).connected&&MST.prim(one).connected,"Single vertex");Graph ties=new Graph(3,false);ties.add(0,1,1);ties.add(1,2,1);ties.add(0,2,1);check(MST.kruskal(ties).weight==2&&MST.prim(ties).weight==2,"Duplicate weights / multiple MSTs");Graph dag=new Graph(4,true);dag.add(0,1,1);dag.add(0,2,1);dag.add(1,3,1);dag.add(2,3,1);check(Connectivity.topological(dag).size()==4,"DAG");dag.add(3,0,1);check(Connectivity.topological(dag).isEmpty(),"Cycle");check(Connectivity.scc(dag).size()==1,"SCC");Graph comps=new Graph(4,true);comps.add(0,1,1);comps.add(1,0,1);comps.add(2,3,1);check(Connectivity.scc(comps).size()==3,"SCC partitions");System.out.println("All correctness tests passed.");}
 public static void main(String[]args)throws Exception{tests();Path out=Paths.get("results/tables/benchmark.csv");Files.createDirectories(out.getParent());StringBuilder csv=new StringBuilder("graph,V,E,algorithm,average_ms,operations,detail\n");for(int[]sz:SIZES){int n=sz[0],m=sz[1];Graph u=undirected(n,m,42+n),d=directed(n,m,100+n,false),dag=directed(n,m,200+n,true);MST.Result k=MST.kruskal(u),p=MST.prim(u);check(k.connected&&p.connected&&k.weight==p.weight,"MST agreement");for(String alg:new String[]{"Kruskal","Prim","Kosaraju","Topological_DAG","Topological_Cyclic","Dijkstra"}){Graph x=alg.equals("Topological_DAG")?dag:d;Job job;long ops;String detail="";switch(alg){case "Kruskal":job=()->MST.kruskal(u).operations;ops=k.operations;detail="mst_weight="+k.weight;break;case "Prim":job=()->MST.prim(u).operations;ops=p.operations;detail="mst_weight="+p.weight;break;case "Kosaraju":job=()->Connectivity.scc(x).size();ops=Connectivity.sccOperations(x);detail="components="+Connectivity.scc(x).size();break;case "Topological_DAG":case "Topological_Cyclic":job=()->Connectivity.topological(x).size();ops=Connectivity.topologicalOperations(x);detail="has_cycle="+Connectivity.topological(x).isEmpty();break;default:job=()->Dijkstra.run(u,0).operations;ops=Dijkstra.run(u,0).operations;detail="source=0";}double ms=bench(job);csv.append(String.format(Locale.US,"%s,%d,%d,%s,%.6f,%d,%s%n",n==10?"Small":n==100?"Medium":"Large",n,m,alg,ms,ops,detail));System.out.printf(Locale.US,"%d %s: %.4f ms, %d operations%n",n,alg,ms,ops);}}Files.writeString(out,csv);System.out.println("Saved "+out);}
}
